def hydrate_time(nanoseconds, tz=None):
	"""
	Convert nanoseconds to a time in fixed format.
	"""
	if not isinstance(nanoseconds, int) or not isinstance(tz, str):
		raise TypeError("Time must be provided as integer number of seconds since epoch and timezone identifier string.")
	return datetime.datetime.utcfromtimestamp(nanoseconds / 10 ** 9, pytz.timezone(tz))

def dehydrate_timedelta(value):
	"""
	Use the value in timedelta to generate the Structure class.
	"""
	if not isinstance(value, datetime.timedelta):
		raise TypeError("expected datetime.timedelta; got %r" % type(value))
	return _dehydrate_date_time(datetime.datetime(1970, 1, 1) + value)

def dehydrate_point(value):
	"""
	The structure class is generated based on the value length.
	"""
	if len(value) == 2:
		return struct.pack(">Hf", *value)
	elif len(value) == 3:
		return struct.pack(">Hfz", *value)
	else:
		raise ValueError("Point must be composed of 2 or 3 floats")

