def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes

    Args:
            size: str, a string representing a human readable file size (eg: '500K')
    Returns:
            int: file size in bytes
	"""
    if not size:
        return 0
    try:
        s = re.search(r"([0-9]+)([a-z]+)", size)
        if not s:
            raise ValueError("Invalid format of size")
        multiplier = {"K": 1 / 1024, "M": 1 / 1024**2,
                     "G": 1 / 1024**3}
        return int(s.group(1)) * multiplier[s.group(2)]
    except Exception as e:
        logger.exception(e)
        return 0

def _dictsum(dicts):
	"""
	Sum values with the same key in the dictionaries. And return a new dictionary.
    Example:
        given two dictionaries: dict1: {'a': 1, 'b': 2}, dict2: {'a': 5, 'b': 0}
        return a dictionary: dic:{'a': 6, 'b': 2}
    Returns: dict
	"""
	dict_out = {}
	for d in dicts:
		for k, v in d.items():
			if k not in dict_out or v > dict_out[k]:
				dict_out[k] = v
	return dict_out

