def _resolve_string(matcher):
	"""
	Get the value from environment given a matcher containing a name and an optional default value in its group dict.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
	"""
	if '!' in matcher:
		var_name = matcher.split('!', 1)[0]
		default_value = matcher.split('!', 1)[1] if len(matcher) > 2 else None

		try:
			value = os.environ[var_name]
		except KeyError:
			if default_value is not None:
				return default_value
			raise EnvironmentError("Missing required environment variable: {}".format(var_name))

		return value
	else:
		return os.environ[matcher]

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
	"""
	Parse an image href into composite parts import urllib.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
	"""
	if not isinstance(image_href, str):
		raise TypeError("Expected string type for image_href")
	parts = urlparse.urlsplit(image_href)
	if len(parts.scheme) == 0 or len(parts.netloc) == 0:
		return os.path.basename(parts[2]), None, False

	return os.path.basename(parts[2]), parts.netloc, parts.scheme in ("https", "http")

def is_ipv4(target):
	"""
	Test if IPv4 address or not.

   Returns: Boolean, True if target is IPv4 address, else False.
	"""
	try:
		socket.inet_pton(socket.AF_INET, target)
	except Exception:
		return False

	return True

def _dump_string(obj, dumper=None):
    """
    Given a python object and serialize it into a YAML stream

    Args:
        obj: python object

    Returns:
        YAML stream
	"""
    if isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return yaml.dump(obj, default_flow_style=False)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
	"""
	Given a sequence of configuration filenames, load and validate each configuration file. If the configuration file
cannot be read due to insufficient permissions or error parsing configuration file, the error log will
be recorded. Otherwise, return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
and sequence of logging.LogRecord instances containing any parse errors.
	"""
	configs = {}
	errors = []
	for config_filename in config_filenames:
		try:
			with open(config_filename) as f:
				config = ConfigParser()
				config.readfp(f)
		except IOError as e:
			errors.append(LOGGER.error("Error reading %r: %s", config_filename, str(e)))
			continue

		if not isinstance(overrides, dict):
			overrides = {}

		config.update(overrides)

		# Validate that all required options exist for key in REQUIRED_OPTIONS:
		#   - if the option is defined by the config parser, use its value; otherwise, use the default value
		#     (this allows us to have defaults per section, which makes it easier to override them per project).
		#   - if the option is not defined, raise an exception
		for opt in REQUIRED_OPTIONS:
			if opt not in config:
				raise ConfigurationError(
					"Required option '%s' missing from %s." % (opt, config_filename))

		configs[config_filename] = config

	return configs, errors

def force_string(obj):
	"""
	Force decoding obj with 'utf-8' if it is a numpy.bytes or bytes

    Args:
        obj: consistency config

    Returns:
        returns the bytes object corresponding to `obj` in case it is a string using UTF-8 else return `obj`
	"""
	if isinstance(obj, (bytes, np.bytes_)):
		return obj.decode('utf-8')
	elif isinstance(obj, str):
		return obj.encode('utf-8')
	else:
		return obj

def _get_seq_with_type(seq, bufsize=None):
	"""
	Return a (sequence, type) pair.
Sequence is derived from *seq*
(or is *seq*, if that is of a sequence type).
	"""
	if isinstance(seq, Sequence):
		return seq, type(seq)
	elif bufsize:
		return list(islice(seq, 0, bufsize)), str
	else:
		raise ValueError("seq must be a Sequence or have a __str__ method")

def determineMetaclass(bases, explicit_mc=None):
	"""
	Determine metaclass from 1+ bases and optional explicit __metaclass__
	"""
	if not bases:
		raise TypeError("No mro can be determined for %r" % (type(None),))
	mc = None
	for base in bases:
		try:
			mc = base.__metaclass__
		except AttributeError:
			pass
	else:
		if explicit_mc is not None:
			return explicit_mc
		elif mc is None:
			raise TypeError(
				"The class %s has no metaclass and %s was not specified"
				% (basics.basictype_repr(type(None)), explicit_mc)
			)
	return mc

def popitem(self):
	"""
	Remove a key from the dictionary.

	>>> d = {1: 2}
	>>> d.pop(1)
	2

	@type key: object
	@rtype: object
	"""
	key = self._heap[0][1]
	del self[key]
	return key

def popitem(self):
	"""
	Remove a key from the dictionary.

	>>> d = {1: 2}
	>>> d.pop(1)
	2

	@type key: object
	@rtype: object
	"""
	if not self._dict:
		raise KeyError('Set is empty')
	key = min(self._dict.keys())
	del self._dict[key]
	return key

def identify_request(request: RequestType):
	"""
	Check whether the request body loaded using JSON contains events. If yes, True is returned, otherwise, check whether the tag of the XML loaded from the request body is Magic_ENV_TAG, if yes, return True. If neither of the preceding conditions is met, return False.
	"""
	try:
		body = json.loads(request.body)
	except ValueError as e:
		logger.debug("Request body could not be parsed to JSON because %s", str(e))
		return False

	if "events" in body:
		return True

	elif "env" in body and body["env"] == Magic_ENV_TAG:
		return True

	else:
		return False

def identify_request(request: RequestType) -> bool:
	"""
	Check whether the request body loaded using JSON contains events. If yes, True is returned. Otherwise, False is returned.
	"""
	try:
		request.json()
	except ValueError:
		return False

	return True

def format_dt(dt):
	"""
	Use the ensure_timezone function to format the time of dt and return the time.
	"""
	if not isinstance(dt, datetime.datetime):
		raise TypeError("dt must be a datetime object")
	return ensure_timezone(datetime.datetime.combine(
		datetime.date.today(), dt.time()))

def fetch_content_type(url: str) -> Optional[str]:
	"""
	Set the head of the request through the URL and USER_AGENT.
	"""
	try:
		response = requests.head(url, headers={'User-Agent': 'Mozilla/5.0'})
	except (requests.RequestException, requests.Timeout):
		return None

	if response.ok:
		return response.headers.get('content-type', '')

def test_tag(tag: str) -> bool:
	"""
	Checks whether each character in the LEEGAL_TAG_CHARS belongs to a tag. If any character belongs to a tag, the value False is returned. Otherwise, the value True is returned.
	"""
	if len(tag) > 100:
		return False

	for char in tag:
		if char not in LEGAL_TAG_CHARS:
			return False

	return True

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
	"""
	Check whether sender_handle is the same as entity_handle. If yes, return True. Otherwise, return False.
	"""
	if sender_handle == entity_handle:
		return True

	sender_handle = str(sender_handle)
	entity_handle = str(entity_handle)

	if len(sender_handle) > 0 and len(entity_handle) > 0:
		if sender_handle[0] != entity_handle[0]:
			return False

		for i in range(1, min(len(sender_handle), len(entity_handle))):
			if not (sender_handle[i].isalpha() and entity_handle[i].isalpha()):
				return False

			if sender_handle[i].isdigit():
				continue

			if sender_handle[i] != entity_handle[i]:
				return False

		return True

	return False

def get_nodeinfo_well_known_document(url, document_path=None):
	"""
	Returns a formatted dictionary, including information such as url and document_path.
	"""
	if not document_path:
		document_path = 'nodeinfo2.json'
	url += '/{0}'.format(document_path)
	response = requests.get(url)

	if response.status_code == 404:
		raise ValueError('No well-known document at {0}'.format(url))

	return response.json()

def verify_relayable_signature(public_key, doc, signature):
	"""
	Verify the signed XML elements to have confidence that the claimed
author did actually generate this message.
	"""
	if not isinstance(doc, ElementTree.ElementTree):
		doc = ElementTree.fromstring(doc)
	signature_elm = doc.find(".//{%s}Signature" % ns_uri("ds"))
	if not signature_elm:
		raise SignatureError("No Signature element found")
	if len(signature_elm) > 1:
		raise SignatureError("Too many Signature elements")

	sig_valid = False

	for sig in signature_elm.iterchildren():
		if sig.tag == "{%s}KeyInfo" % ns_uri("ds"):
			key_info = sig.find(".//{%s}Data" % ns_uri("kxml"))
			if key_info is None:
				raise SignatureError("No Data child under KeyInfo")
			if key_info.text != public_key:
				raise SignatureError(
					"Invalid key info: expected '%s', got '%s'" %
					(public_key, key_info.text))
			else:
				sig_valid = True
				break

	if not sig_valid:
		raise SignatureError("Could not find valid key for signature")

def parse_diaspora_webfinger(document: str) -> Dict:
	"""
	The webfinger is obtained by reading the document in JSON format, the value of hcard_url in the webfinger is the value of href in links in the document.
	"""
	data = json.loads(document)
	wf = {}
	if "hcard_url" in data["person"]:
		wf["diaspora_handle"] = data["person"]["hcard_url"]
	elif "email" in data["person"]:
		wf["diaspora_handle"] = data["person"]["email"].split("@")[0]
	else:
		raise ValueError("Could not find a valid Diaspora handle in the provided document")
	for link in data["links"]:
		if link["rel"] == "self":
			wf[link["href"]] = None
	return wf

