def retrieve_diaspora_host_meta(host):
	"""
	Retrieve a remote Diaspora host-meta document.

:arg host: Host to retrieve from
:returns: ``XRD`` instance
	"""
	url = "https://%s/.well-known/host-meta" % (host,)
	try:
		response = requests.get(url)
	except Exception as e:
		raise DiasporaHostMetaRetrievalError(str(e))
	if response.status_code != 200:
		raise DiasporaHostMetaRetrievalError("Got back status code %d instead of 200 when retrieving host meta for %s." % (
			response.status_code,
			host,
		))
	return XRD.from_string(response.text)

def get_deprecated_args(self):
	"""
	Returning dict with options which deprecate others. options from self.spec_helper.iterate_option_specs()
	"""
	deprecated = {}
	for option in self.spec_helper.iterate_option_specs():
		if option.deprecated:
			deprecated[option.name] = option

	return deprecated

def validate_arg_deprecated(self, cli_args, answer_file_args):
	""" Validates and prints the deprecated arguments.

:param cli_args: the dict of arguments from cli
:param answer_file_args:  the dict of arguments from files
	"""
	for arg in self.deprecated_arguments:
	    if (arg in cli_args or arg in answer_file_args) and not self.ignore_deprecated:
	        print("DEPRECATED: %s" % arg)
	        if arg in cli_args:
	            del cli_args[arg]
	        elif arg in answer_file_args:
	            del answer_file_args[arg]

def get_parser_option_specs(self, command_name):
	"""
	Gets all the options for the specified command

:param command_name: the command name (main, virsh, ospd, etc...)
:return: the list of all command options
	"""
	options = []
	for option in self._parser.option_list:
		if option.dest == 'commands':
			continue
		if not hasattr(option, 'metavar'):
			option.metavar = option.dest.upper()
		if not hasattr(option, 'help'):
			option.help = "No help available"
		if hasattr(option, 'default') and \
				(option.default is None or option.default == []):
			option.default = ''
		if hasattr(option, 'choices'):
			if len(option.choices) > 10:
				option.talks_to_choices = True
			else:
				for choice in option.choices:
					if isinstance(choice, str):
						pass
					elif isinstance(choice, Command):
						pass
					else:
						raise ValueError("Choices must be a string or a Command instance")
		options.append((option.dest, option))
	return options

def get_option_spec(self, command_name, argument_name):
		"""
		Gets the specification for the specified option name. Get options of the given command_name with self.get_parser_option_specs()
		"""
		if not command_name in self._parser.option_registrations:
			raise Exception("Unknown command: %s" % command_name)
		for opt in self._parser.option_registrations[command_name]:
			if opt.dest == argument_name:
				return opt.parser_spec
		raise Exception("No such argument: %s" % argument_name)

def get_silent_args(self, args):
	"""
	list of silenced argument

:param args: The received arguments.
:return: list, slienced argument names
	"""
	silence = []
	for arg in args:
	    if isinstance(arg, (list, tuple)):
	        silence.extend(self.get_silent_args(arg))
	    elif isinstance(arg, dict):
	        for key in arg.keys():
	            if key.startswith('_'):
	                silence.append(key)
	    else:
	        silence.append(arg)

	return silence

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                     spec_option):
		"""
	Returns the corresponding function in COMPLEX_TYPES based on type_name and returns the result obtained by complex_action after option_name,(self.vars, self.defaults, self.plugin_path), subcommand, spec_option) is input.
		"""
		if type_name == 'choice':
			return self.create_choice_type(subcommand, option_name, spec_option)
		elif type_name == 'flag':
			return self.create_flag_type(subcommand, option_name, spec_option)
		elif type_name == 'file':
			return self.create_file_type(subcommand, option_name, spec_option)
		elif type_name == 'directory':
			return self.create_directory_type(subcommand, option_name, spec_option)
		elif type_name == 'list':
			return self.create_list_type(subcommand, option_name, spec_option)
		elif type_name == 'string':
			return self.create_string_type(subcommand, option_name, spec_option)
		elif type_name == 'type':
			return self.create_type_type(subcommand, option_name, spec_option)
		else:
			raise ValueError('Invalid type name: %s' % type_name)

def get_nested_custom_and_control_args(self, args):
	"""Split input arguments to control nested and custom.

Controls arguments: control the IR behavior. These arguments
    will not be put into the spec yml file
Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.

:param args: the collected list of args.
:return: (dict, dict): flat dicts (control_args, nested_args)
	"""
	nested_args = {}
	control_args = {}

	for arg in args:
		if self.is_nested(arg):
			nested_args[arg] = None
		elif self.is_control(arg):
			control_args[arg] = None

	return control_args, nested_args

def _convert_non_cli_args(self, parser_name, values_dict):
	"""
	Casts arguments to correct types by modifying values_dict param.

By default all the values are strings.
:param parser_name: The command name, e.g. main, virsh, ospd, etc
:param values_dict: The dict of with arguments
	"""
	if not self._parser:
	    return

	for arg in self._parser.getnonoptionargs(parser_name):
	    if arg in values_dict:
		value = values_dict[arg]
		try:
		    value = int(value)
		except ValueError:
		    pass
		values_dict[arg] = value

def get_plugin_spec_flatten_dict(plugin_dir):
	"""
	Use YAML to read various information in plugin_dir and return the information in dictionary form.
	"""
	spec = {}
	for root, dirs, files in os.walk(plugin_dir):
		if not dirs:
			dir_name = os.path.basename(root)
			if dir_name.startswith('_'):
				continue
			spec[dir_name] = {}
			for f in files:
				file_name = os.path.splitext(f)[0]
				if file_name == 'plugin':
					with open(os.path.join(root, f), 'r') as fp:
						try:
							spec[dir_name][file_name] = yaml.load(fp.read())
						except Exception as e:
							raise PluginSpecError('Failed to parse %s/%s: %s' % (dir_name, file_name, str(e)))
	return spec

def inject_config(self):
		"""
		If the ANSIBLE_CONFIG property does not exist in os.environ, set it to self.ansible_config_path.
		"""
		if 'ANSIBLE_CONFIG' not in os.environ:
			os.environ['ANSIBLE_CONFIG'] = self.ansible_config_path
